// One entry shape for both channels. route: process | reject_web | ignore
const MAX_QUESTION = 1000;
const item = $input.first().json;
const clean = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
let out;

if (item.message) {
  // Telegram update
  const t = item.message;
  const text = clean(t.text);
  out = {
    channel: 'telegram',
    session_id: 'tg-' + t.chat.id,
    chat_id: String(t.chat.id),
    user_name: [t.from && t.from.first_name, t.from && t.from.last_name].filter(Boolean).join(' '),
    question: text.slice(0, MAX_QUESTION),
    history: [], // add a memory node if the Telegram bot should remember earlier turns
    route: text && !text.startsWith('/') ? 'process' : 'ignore', // commands and non-text updates are skipped
  };
} else {
  // Website widget: POST { message, session_id?, history?, user?: { name } }
  const b = item.body || {};
  const question = clean(b.message);
  const history = (Array.isArray(b.history) ? b.history : []).slice(-6).map((h) => ({
    role: h && h.role === 'assistant' ? 'assistant' : 'user',
    content: clean(h && h.content).slice(0, 500),
  }));
  out = {
    channel: 'web',
    session_id: clean(b.session_id).slice(0, 64) || 'web-' + Date.now(),
    chat_id: '',
    user_name: clean(b.user && b.user.name).slice(0, 80),
    question,
    history,
    route: question && question.length <= MAX_QUESTION ? 'process' : 'reject_web',
  };
  if (out.route === 'reject_web') {
    out.error = question ? `message is longer than ${MAX_QUESTION} characters` : 'message is required';
  }
}
return [{ json: out }];

// Understands two knowledge-base shapes and keeps only passages that score above KB_MIN_SCORE:
//   1. JSON { results: [{ text, source, score }] }  (the mock service, or any small search endpoint)
//   2. docs-rag-assistant POST /api/chat server-sent events: the "sources" event carries the passages
const q = $('Normalize message').first().json;
const MIN_SCORE = Number($env.KB_MIN_SCORE || 0.4);
const MAX_PASSAGES = 4;
const res = $input.first().json;
let hits = [];
let kbError = '';

function sseSources(text) {
  for (const block of text.split(/\r?\n\r?\n/)) {
    if (!/^event:\s*sources/m.test(block)) continue;
    const line = block.split(/\r?\n/).find((l) => l.startsWith('data:'));
    if (line) return JSON.parse(line.slice(5).trim()).sources || [];
  }
  return [];
}

try {
  if (res.error) throw new Error(typeof res.error === 'string' ? res.error : res.error.message || 'request failed');
  const raw = typeof res.data === 'string' ? res.data.trim() : JSON.stringify(res);
  if (raw.startsWith('{')) {
    const j = JSON.parse(raw);
    hits = (j.results || j.sources || []).map((r) => ({ text: r.text, source: r.source || r.filename || r.title || 'kb', score: Number(r.score) }));
  } else if (raw.includes('event: sources')) {
    hits = sseSources(raw).map((r) => ({ text: r.text, source: r.filename + (r.page ? ', p.' + r.page : ''), score: Number(r.score) }));
  }
} catch (e) {
  kbError = String(e.message || e).slice(0, 300);
}

hits.sort((a, b) => b.score - a.score);
const context = hits
  .filter((h) => h.text && h.score >= MIN_SCORE)
  .slice(0, MAX_PASSAGES)
  .map((h, i) => ({ n: i + 1, ...h }));
// Escaped so a passage cannot close the tag or fake an instruction block; the prompt treats it as data.
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return [
  {
    json: {
      ...q,
      kb_error: kbError,
      has_context: context.length > 0,
      top_score: context.length ? context[0].score : 0,
      best_score: hits.length ? hits[0].score : 0, // best passage even if it was below the threshold
      min_score: MIN_SCORE,
      context,
      context_text: context.map((c) => `<passage id="${c.n}" source="${esc(c.source)}">\n${esc(c.text)}\n</passage>`).join('\n'),
    },
  },
];

// Demo only (no LLM): "answer" with the best passage, in the same shape the Claude step returns.
// The score is capped at 1 because some backends (BM25) are not 0..1.
const kb = $input.first().json;
const top = kb.context[0];
return [{ json: { output: { answer: `${top.text} (source: ${top.source})`, confidence: Math.min(1, top.score), answerable: true, sources: [top.n] } } }];

// Answer only when the knowledge base had context AND the model returned a valid, answerable,
// confident result. Everything else becomes "I'm not sure" plus an escalation to a human.
const NOT_SURE = "I'm not sure about that one. I've passed your question to our team and someone will follow up with you shortly.";
const MIN_CONFIDENCE = Number($env.ANSWER_MIN_CONFIDENCE || 0.6);
const kb = $('Parse KB response').first().json;

function parse(raw) {
  if (typeof raw !== 'string') return raw;
  const m = raw.match(/\{[\s\S]*\}/);
  if (!m) return null;
  try {
    return JSON.parse(m[0]);
  } catch (e) {
    return null;
  }
}

let answer = null;
let confidence = 0;
let reason = '';

if (!kb.has_context) {
  if (kb.kb_error) reason = 'knowledge base unavailable: ' + kb.kb_error;
  else if (kb.best_score > 0) reason = `no passage scored above ${kb.min_score} (best: ${kb.best_score})`;
  else reason = 'no relevant context found';
} else {
  const item = $input.first().json;
  const c = parse(item.output !== undefined ? item.output : item);
  const valid =
    c && typeof c === 'object' && typeof c.answer === 'string' &&
    typeof c.answerable === 'boolean' && typeof c.confidence === 'number' && c.confidence >= 0 && c.confidence <= 1;
  if (!valid) {
    reason = 'invalid model output';
  } else {
    confidence = c.confidence;
    if (!c.answerable) reason = 'the context does not answer the question';
    else if (!c.answer.trim()) reason = 'invalid model output';
    else if (confidence < MIN_CONFIDENCE) reason = `low confidence (${confidence})`;
    else answer = c.answer.trim().slice(0, 1500);
  }
}

const escalate = answer === null;
const reply_text = escalate ? NOT_SURE : answer;
const conversation = kb.history
  .map((h) => `${h.role === 'assistant' ? 'Bot' : 'Customer'}: ${h.content}`)
  .concat(`Customer: ${kb.question}`, `Bot: ${reply_text}`)
  .join('\n');

return [
  {
    json: {
      channel: kb.channel,
      session_id: kb.session_id,
      chat_id: kb.chat_id,
      user_name: kb.user_name,
      question: kb.question,
      reply_text,
      answered: !escalate,
      escalate,
      escalate_reason: reason,
      confidence,
      sources: escalate ? [] : [...new Set(kb.context.map((c) => c.source))],
      slack_text:
        `*Support bot could not answer* (${reason})\n` +
        `Channel: ${kb.channel} | Session: ${kb.session_id}${kb.user_name ? ' | ' + kb.user_name : ''}\n\n` +
        `*Conversation*\n${conversation}`,
      logged_at: $now.toISO(),
    },
  },
];
